#!/usr/bin/env bash
# Regression cases for no-claude-commits.sh. Each case is one commit on top of a
# clean base; expect FAIL (blocked) or PASS. Runs on macOS's stock bash 3.2 too.
set -uo pipefail
SCRIPT="$(cd "$(dirname "$1")" && pwd)/$(basename "$1")"
T="$(mktemp -d "${TMPDIR:-/tmp}/nocl-test.XXXX")"
cd "$T" && git init -q && git config user.name "Aaron Cupp" && git config user.email "a@example.com" && git config commit.gpgsign false
git commit -q --allow-empty -m base
base="$(git rev-parse HEAD)"
# Never spell the name or the trailer in full on a command line.
C=Cla; C="${C}ude"; c=cla; c="${c}ude"; CO="Co-Authored-By"; co="Co-authored-by"
R='\xf0\x9f\xa4\x96'
A="Aaron Cupp"; E="a@example.com"
pass=0; fail=0
check() { # expect author-name author-email message [committer-name committer-email]
  local expect="$1" name="$2" email="$3" msg="$4" cname="${5:-$A}" cemail="${6:-$E}"
  git reset -q --hard "$base"
  GIT_AUTHOR_NAME="$name" GIT_AUTHOR_EMAIL="$email" GIT_COMMITTER_NAME="$cname" GIT_COMMITTER_EMAIL="$cemail" \
    git commit -q --allow-empty --cleanup=verbatim -F <(printf '%b' "$msg")
  if BASE="$base" HEAD=HEAD "$SCRIPT" >/dev/null 2>&1; then got=PASS; else got=FAIL; fi
  if [ "$got" = "$expect" ]; then pass=$((pass+1)); else fail=$((fail+1)); echo "WRONG ($got, want $expect): $name <$email> / $cname <$cemail> :: $msg"; fi
}

# --- blocked: identity (author, then committer)
check FAIL "$C" "noreply@anthropic.com" "feat: x"
check FAIL "$C" "x@example.com" "feat: x"
check FAIL "$C Code" "x@example.com" "feat: x"
check FAIL "$C Opus" "x@example.com" "feat: x"
check FAIL "$c[bot]" "123+$c[bot]@users.noreply.github.com" "feat: x"
check FAIL "$A" "$c[bot]@users.noreply.github.com" "feat: x"
check FAIL "$A" "someone@anthropic.com" "feat: x"
check FAIL "$A" "$E" "feat: x" "$C" "noreply@anthropic.com"
check FAIL "$A" "$E" "feat: x" "$A" "209825114+$c[bot]@users.noreply.github.com"
# --- blocked: trailers in the body
check FAIL "$A" "$E" "feat: x\n\n$CO: $C Opus 5.5 <noreply@anthropic.com>"
check FAIL "$A" "$E" "feat: x\n\n$co: $C <noreply@anthropic.com>"
check FAIL "$A" "$E" "feat: x\n\n$CO:$C <x@example.com>"
check FAIL "$A" "$E" "feat: x\n\n  $CO: $C"
check FAIL "$A" "$E" "feat: x\n\n$CO: $C-Code <x@example.com>"
check FAIL "$A" "$E" "feat: x\n\n$CO: \"$C\" <x@example.com>"
check FAIL "$A" "$E" "feat: x\n\n$CO: $C <noreply@mail.anthropic.com>"
check FAIL "$A" "$E" "feat: x\n\n$CO: Someone <209825114+$c[bot]@users.noreply.github.com>"
check FAIL "$A" "$E" "feat: x\n\nSigned-off-by: $C <noreply@anthropic.com>"
check FAIL "$A" "$E" "feat: x\n\nSigned-off-by: $c[bot] <1+$c[bot]@users.noreply.github.com>"
check FAIL "$A" "$E" "feat: x\n\nAssisted-by: $C"
check FAIL "$A" "$E" "feat: x\n\nGenerated-by: $C Code"
check FAIL "$A" "$E" "feat: x\n\nReviewed-by: $C <noreply@anthropic.com>"
# --- blocked: the footer, however it's written
check FAIL "$A" "$E" "feat: x\n\n$R Generated with [$C Code](https://claude.com/claude-code)"
check FAIL "$A" "$E" "feat: x\n\n$R Generated with [$C Code](https://claude.com/claude-code)\r"
check FAIL "$A" "$E" "feat: x\n\nGenerated with $C Code"
check FAIL "$A" "$E" "feat: x\n\nGenerated with $C Code."
check FAIL "$A" "$E" "feat: x\n\nGenerated with $C Code (https://claude.com/claude-code)"
check FAIL "$A" "$E" "feat: x\n\nGenerated with $C Opus 4.5"
check FAIL "$A" "$E" "feat: x\n\nGenerated using $C Code"
check FAIL "$A" "$E" "feat: x\n\nGENERATED WITH $C CODE"
# --- allowed: subjects that only talk about Claude or the footer
check PASS "$A" "$E" "docs: $C may review PRs"
check PASS "$A" "$E" "docs: explain why a Generated with $C Code footer fails CI"
check PASS "$A" "$E" "fix: reject text generated by $c in the log"
check PASS "$A" "$E" "Generated with $C Code"
check PASS "$A" "$E" "Signed-off-by: $C lines are blocked now"
check PASS "$A" "$E" "chore(repo): ignore the $C outputs folder\n\nSigned-off-by: Aaron Cupp <a@example.com>"
check PASS "$A" "$E" "Merge pull request #9 from x/y\n\ndocs: explain why a Generated with $C Code footer fails CI"
check PASS "$A" "$E" "feat: x\n\nThis drops the $C-specific config."
# --- allowed: people whose names merely contain it
check PASS "Jean-$C" "jc@example.com" "feat: x"
check PASS "$A" "$E" "feat: x\n\n$CO: Jean-$C Dupont <jc@example.com>"
check PASS "$A" "$E" "feat: x\n\n$CO: ${C}tte <c@example.com>"
# --- allowed: the usual machine identities
check PASS "GitHub" "noreply@github.com" "Merge pull request #1 from x/y" "GitHub" "noreply@github.com"
check PASS "github-actions[bot]" "41898282+github-actions[bot]@users.noreply.github.com" "chore(main): release 1.0.0"
check PASS "dependabot[bot]" "49699333+dependabot[bot]@users.noreply.github.com" "build(deps): bump x\n\nSigned-off-by: dependabot[bot] <support@github.com>"

# A workflow command in the body must come out indented, never at column 0.
git reset -q --hard "$base"
git commit -q --allow-empty -F <(printf 'feat: x\n\n%s: %s <n@anthropic.com>\n::warning::spoof' "$CO" "$C")
out="$(BASE="$base" HEAD=HEAD "$SCRIPT" 2>&1 || true)"
if grep -q '^::warning' <<< "$out"; then fail=$((fail+1)); echo "WRONG: unindented ::warning line"; else pass=$((pass+1)); fi

echo "$pass passed, $fail wrong"
rm -rf "$T"
[ "$fail" = 0 ]
